head.script:

	scwin.onpageload = function() {
        var row = 100;
        var col = 5;
        var data = [];
        for(var i = 0; i < row; i++){
            for(var j = 0; j < col; j++){
                data.push((i * row + j) + ""); 
            }
        }
        dataList1.setData(data);
        dataMap1.set("key1", "col1");
        output1.setValue(dataList1.ignoreStatusColArr);
	};

	scwin.onpageunload = function() {

	};


	scwin.trigger1_onclick = function(e) {
		dataList1.setIgnoreStatus(input1.getValue(), true);
        output1.setValue(dataList1.ignoreStatusColArr);
	};
    scwin.trigger2_onclick = function(e) {
        dataList1.setIgnoreStatus(input1.getValue(), false);
        output1.setValue(dataList1.ignoreStatusColArr);
    };
    // 확장된 기능1
    scwin.trigger3_onclick = function(e) {
        dataList1.setIgnoreStatus(true);
        output1.setValue(dataList1.ignoreStatusColArr);
    };
    // 확장된 기능2
    scwin.trigger4_onclick = function(e) {
        dataList1.setIgnoreStatus(false);
        output1.setValue(dataList1.ignoreStatusColArr);
    };


	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'gridView1__col1', 'key-sequence', {
			sequence: '5'
		});
	}
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'gridView1__col1', 'key-sequence', {
			sequence: '6'
		});
	}	
	scwin.setSimulate3 = function() {
		scwin.simulateWrapper('#G_'+$p.id+'gridView1__col2', 'key-sequence', {
			sequence: '111'
		});
	}	
	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('gridView1_headerRowStatus_bodyRow_0').classList.contains('w2grid_rowStatus_R');
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('gridView1_headerRowStatus_bodyRow_0').classList.contains('w2grid_rowStatus_U');
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('gridView1_headerRowStatus_bodyRow_1').classList.contains('w2grid_rowStatus_R');
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_0')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_0_0')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_1_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_cell_1_1')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
